1	package remote
2	
3	import (
4		"context"
5		"fmt"
6		"log/slog"
7		"os"
8		"sort"
9		"strings"
10	
11		"github.com/entireio/cli/cmd/entire/cli/gitremote"
12		"github.com/entireio/cli/cmd/entire/cli/logging"
13		"github.com/entireio/cli/cmd/entire/cli/settings"
14	
15		"github.com/go-git/go-git/v6"
16	)
17	
18	const originRemote = "origin"
19	
20	const (
21		ProtocolSSH   = gitremote.ProtocolSSH
22		ProtocolHTTPS = gitremote.ProtocolHTTPS
23	)
24	
25	// Info is an alias for gitremote.Info.
26	type Info = gitremote.Info
27	
28	// FetchURLOptions configures FetchURL.
29	type FetchURLOptions struct {
30		WorktreeRoot string
31	}
32	
33	// FetchURL returns the effective checkpoint fetch URL for the current repository.
34	// If strategy_options.checkpoint_remote is configured, the returned URL is derived
35	// from the origin remote's protocol/host and the configured checkpoint repo.
36	// Otherwise, the origin remote URL is returned directly.
37	//
38	// If ENTIRE_CHECKPOINT_TOKEN is set and a checkpoint remote is configured, HTTPS is
39	// forced so the token can be used even when origin is configured via SSH.
40	func FetchURL(ctx context.Context, opts ...FetchURLOptions) (string, error) {
41		var opt FetchURLOptions
42		if len(opts) > 0 {
43			opt = opts[0]
44		}
45	
46		getRemoteURL := GetRemoteURL
47		if opt.WorktreeRoot != "" {
48			ctx = settings.WithWorktreeRoot(ctx, opt.WorktreeRoot)
49			getRemoteURL = func(ctx context.Context, remoteName string) (string, error) {
50				return GetRemoteURLInDir(ctx, opt.WorktreeRoot, remoteName)
51			}
52		}
53	
54		withToken := strings.TrimSpace(os.Getenv(CheckpointTokenEnvVar)) != ""
55	
56		originURL, originErr := getRemoteURL(ctx, originRemote)
57		if originErr != nil {
58			originURL = ""
59		}
60	
61		if originURL != "" && withToken {
62			if tokenURL, ok := deriveTokenOriginURL(originURL); ok {
63				originURL = tokenURL
64			}
65		}
66	
67		s, err := settings.Load(ctx)
68		if err != nil {
69			if originURL != "" {
70				logFallback(ctx, "fetch", originURL, "load settings", err)
71				return originURL, nil
72			}
73			return "", fmt.Errorf("load settings: %w", err)
74		}
75	
76		config := s.GetCheckpointRemote()
77		if config == nil {
78			if originURL == "" {
79				return "", fmt.Errorf("no fetch URL found: %w", originErr)
80			}
81			return originURL, nil
82		}
83	
84		if withToken {
85			host, ok := providerHost(config.Provider)
86			if ok {
87				checkpointURL, err := deriveCheckpointURLFromInfo(&Info{
88					Protocol: ProtocolHTTPS,
89					Host:     host,
90				}, config)
91				if err == nil {
92					return checkpointURL, nil
93				}
94			}
95	
96			// In token-based execution path, short-circuit to avoid additional
97			// change in protocol.
98			if originURL != "" {
99				return originURL, nil
100			}
101		}
102	
103		if originURL == "" {
104			return "", fmt.Errorf("no fetch URL found: %w", originErr)
105		}
106	
107		info, err := ParseURL(originURL)
108		if err != nil {
109			logFallback(ctx, "fetch", originURL, "parse origin remote URL", err)
110			return originURL, nil
111		}
112	
113		checkpointURL, err := deriveCheckpointURLFromInfo(info, config)
114		if err != nil {
115			// Origin's protocol can't be mapped to a git transport (e.g. entire://,
116			// file://). Honor the configured checkpoint_remote by targeting the
117			// provider's canonical host over HTTPS rather than falling back to origin.
118			if providerURL, ok := resolveProviderCheckpointURL(config, opt.WorktreeRoot); ok {
119				return providerURL, nil
120			}
121			logFallback(ctx, "fetch", originURL, "derive checkpoint remote URL", err)
122			return originURL, nil
123		}
124	
125		return checkpointURL, nil
126	}
127	
128	// PushURL returns the effective checkpoint push URL for the current repository.
129	// Unlike FetchURL:
130	//   - it derives protocol from the requested push remote, not always origin
131	//   - it skips checkpoint remote use when the push remote owner differs
132	//     from the configured checkpoint remote owner
133	//
134	// If ENTIRE_CHECKPOINT_TOKEN is set, HTTPS is forced so the token can be used
135	// even when the push remote is configured via SSH.
136	//
137	// The boolean return value reports whether a dedicated checkpoint_remote is
138	// configured and should be used for push. When false, the returned URL is the
139	// repository's origin URL as a fallback.
140	func PushURL(ctx context.Context, pushRemoteName string) (string, bool, error) {
141		originURL := ""
142		if resolvedOriginURL, err := GetRemoteURL(ctx, originRemote); err == nil {
143			originURL = resolvedOriginURL
144		}
145	
146		s, err := settings.Load(ctx)
147		if err != nil {
148			fallbackURL, fallbackErr := resolvePushFallbackURL(ctx, pushRemoteName, originURL)
149			if fallbackErr == nil {
150				logFallback(ctx, "push", fallbackURL, "load settings", err,
151					slog.String("push_remote", pushRemoteName),
152				)
153				return fallbackURL, false, nil
154			}
155			return "", false, fmt.Errorf("load settings: %w", err)
156		}
157	
158		config := s.GetCheckpointRemote()
159		if config == nil {
160			fallbackURL, fallbackErr := resolvePushFallbackURL(ctx, pushRemoteName, originURL)
161			if fallbackErr != nil {
162				return "", false, fmt.Errorf("no push URL found: %w", fallbackErr)
163			}
164			return fallbackURL, false, nil
165		}
166	
167		pushRemoteURL, err := GetRemoteURL(ctx, pushRemoteName)
168		if err != nil {
169			fallbackURL, fallbackErr := resolvePushFallbackURL(ctx, pushRemoteName, originURL)
170			if fallbackErr == nil {
171				logFallback(ctx, "push", fallbackURL, "get push remote URL", err,
172					slog.String("push_remote", pushRemoteName),
173				)
174				return fallbackURL, false, nil
175			}
176			return "", true, fmt.Errorf("no push URL found: %w", err)
177		}
178	
179		pushInfo, err := ParseURL(pushRemoteURL)
180		if err != nil {
181			if originURL != "" {
182				logFallback(ctx, "push", originURL, "parse push remote URL", err,
183					slog.String("push_remote", pushRemoteName),
184				)
185				return originURL, false, nil
186			}
187			return "", true, fmt.Errorf("no push URL found: %w", err)
188		}
189		if strings.TrimSpace(os.Getenv(CheckpointTokenEnvVar)) != "" && isDerivableProtocol(pushInfo.Protocol) {
190			// Coerce a derivable (ssh/https) remote to HTTPS so the token applies,
191			// keeping the host so enterprise installations stay on their own host.
192			// A non-derivable protocol (e.g. entire://) carries a host that isn't a
193			// usable HTTPS host, so it's left untouched and falls through to the
194			// providerCheckpointURL fallback below.
195			//
196			// Keep the port only when the source was already HTTPS. SSH ports
197			// (e.g., :2222) don't map to HTTPS ports on the same host.
198			port := ""
199			if pushInfo.Protocol == ProtocolHTTPS {
200				port = pushInfo.Port
201			}
202			pushInfo = &Info{
203				Protocol: ProtocolHTTPS,
204				Host:     pushInfo.Host,
205				Port:     port,
206				Owner:    pushInfo.Owner,
207				Repo:     pushInfo.Repo,
208			}
209		}
210	
211		checkpointOwner := config.Owner()
212		if pushInfo.Owner != "" && checkpointOwner != "" && !strings.EqualFold(pushInfo.Owner, checkpointOwner) {
213			fallbackURL, fallbackErr := resolvePushFallbackURL(ctx, pushRemoteName, originURL)
214			if fallbackErr != nil {
215				return "", false, fmt.Errorf("no push URL found: %w", fallbackErr)
216			}
217			return fallbackURL, false, nil
218		}
219	
220		pushURL, err := deriveCheckpointURLFromInfo(pushInfo, config)
221		if err != nil {
222			// The push remote's protocol can't be mapped to a git transport
223			// (e.g. entire://, file://). Honor the configured checkpoint_remote by
224			// targeting the provider's canonical host over HTTPS rather than
225			// misrouting checkpoints to the origin remote.
226			if providerURL, ok := resolveProviderCheckpointURL(config, ""); ok {
227				return providerURL, true, nil
228			}
229			fallbackURL, fallbackErr := resolvePushFallbackURL(ctx, pushRemoteName, originURL)
230			if fallbackErr == nil {
231				logFallback(ctx, "push", fallbackURL, "derive push checkpoint URL", err,
232					slog.String("push_remote", pushRemoteName),
233				)
234				return fallbackURL, false, nil
235			}
236			return "", true, fmt.Errorf("no push URL found: %w", err)
237		}
238	
239		return pushURL, true, nil
240	}
241	
242	// Configured reports whether a structured checkpoint_remote is configured.
243	func Configured(ctx context.Context) bool {
244		s, err := settings.Load(ctx)
245		if err != nil {
246			logging.Warn(ctx, "checkpoint remote configuration unavailable; treating as not configured",
247				slog.String("error", err.Error()),
248			)
249			return false
250		}
251		return s.GetCheckpointRemote() != nil
252	}
253	
254	// GetRemoteURL returns the URL configured for the named git remote.
255	func GetRemoteURL(ctx context.Context, remoteName string) (string, error) {
256		url, err := gitremote.GetRemoteURL(ctx, remoteName)
257		if err != nil {
258			return "", fmt.Errorf("get remote URL: %w", err)
259		}
260		return url, nil
261	}
262	
263	// GetRemoteURLInDir returns the URL configured for the named git remote in dir.
264	func GetRemoteURLInDir(ctx context.Context, dir, remoteName string) (string, error) {
265		url, err := gitremote.GetRemoteURLInDir(ctx, dir, remoteName)
266		if err != nil {
267			return "", fmt.Errorf("get remote URL: %w", err)
268		}
269		return url, nil
270	}
271	
272	// ParseURL parses a git remote URL (SSH SCP-style or HTTPS) into its components.
273	func ParseURL(rawURL string) (*Info, error) {
274		info, err := gitremote.ParseURL(rawURL)
275		if err != nil {
276			return nil, fmt.Errorf("parse URL: %w", err)
277		}
278		return info, nil
279	}
280	
281	// isDerivableProtocol reports whether deriveCheckpointURLFromInfo can map the
282	// protocol to a checkpoint URL (i.e. it's a real git transport, not a remote
283	// helper scheme like entire:// or a local file://).
284	func isDerivableProtocol(protocol string) bool {
285		return protocol == ProtocolSSH || protocol == ProtocolHTTPS
286	}
287	
288	func deriveCheckpointURLFromInfo(info *Info, config *settings.CheckpointRemoteConfig) (string, error) {
289		switch info.Protocol {
290		case ProtocolSSH:
291			// SCP-style (git@host:repo) doesn't support ports. When a non-default
292			// port is set (e.g., from ssh://git@host:2222/...), use the ssh:// URL form.
293			if info.Port != "" {
294				return fmt.Sprintf("ssh://git@%s/%s.git", info.HostPort(), config.Repo), nil
295			}
296			return fmt.Sprintf("git@%s:%s.git", info.Host, config.Repo), nil
297		case ProtocolHTTPS:
298			return fmt.Sprintf("https://%s/%s.git", info.HostPort(), config.Repo), nil
299		default:
300			return "", fmt.Errorf("unsupported protocol %q in origin remote", info.Protocol)
301		}
302	}
303	
304	// resolveProviderCheckpointURL builds the checkpoint URL for the configured
305	// provider, choosing the transport from what's already configured for that
306	// endpoint. It is the fallback used when the push/origin remote's protocol can't
307	// be mapped to a git transport (e.g. entire://, file://): the configured
308	// checkpoint_remote names a concrete provider, so checkpoints go there rather
309	// than being misrouted to the origin remote.
310	//
311	// Transport precedence:
312	//  1. ENTIRE_CHECKPOINT_TOKEN set -> HTTPS on the provider host (the token is
313	//     the credential).
314	//  2. An existing remote already targets the provider host -> reuse its scheme,
315	//     so checkpoints use the same auth the user already has for that endpoint.
316	//  3. Otherwise SSH on the provider host.
317	//
318	// Returns ok=false when no transport can be determined (unknown provider with no
319	// usable signal), in which case the caller falls back to the origin remote.
320	func resolveProviderCheckpointURL(config *settings.CheckpointRemoteConfig, dir string) (string, bool) {
321		repo, err := openRepoAt(dir)
322		if err != nil {
323			repo = nil // Fall back to env/provider-only signals.
324		}
325	
326		info, ok := pickProviderTransport(repo, config)
327		if !ok {
328			return "", false
329		}
330		url, err := deriveCheckpointURLFromInfo(info, config)
331		if err != nil {
332			return "", false
333		}
334		return url, true
335	}
336	
337	// pickProviderTransport returns the protocol/host/port to use when deriving a
338	// checkpoint URL, following the precedence documented on
339	// resolveProviderCheckpointURL.
340	func pickProviderTransport(repo *git.Repository, config *settings.CheckpointRemoteConfig) (*Info, bool) {
341		host, hostOK := providerHost(config.Provider)
342	
343		// 1. Explicit token -> HTTPS on the provider host.
344		if hostOK && strings.TrimSpace(os.Getenv(CheckpointTokenEnvVar)) != "" {
345			return &Info{Protocol: ProtocolHTTPS, Host: host}, true
346		}
347	
348		// 2. An existing remote already targeting the provider host -> reuse scheme.
349		if hostOK && repo != nil {
350			if info, ok := findRemoteInfoForHost(repo, host); ok {
351				return &Info{Protocol: info.Protocol, Host: info.Host, Port: info.Port}, true
352			}
353		}
354	
355		// 3. Default to SSH on the provider host.
356		if hostOK {
357			return &Info{Protocol: ProtocolSSH, Host: host}, true
358		}
359	
360		return nil, false
361	}
362	
363	// openRepoAt opens the git repository at dir (current directory when dir is
364	// empty), walking up to the enclosing .git directory.
365	func openRepoAt(dir string) (*git.Repository, error) {
366		if dir == "" {
367			dir = "."
368		}
369		repo, err := git.PlainOpenWithOptions(dir, &git.PlainOpenOptions{DetectDotGit: true})
370		if err != nil {
371			return nil, fmt.Errorf("open git repository: %w", err)
372		}
373		return repo, nil
374	}
375	
376	// findRemoteInfoForHost returns the parsed Info of the first configured git
377	// remote (in deterministic name order) whose host matches host and whose
378	// protocol is a usable git transport (ssh/https). entire:// and other
379	// non-transport remotes are ignored.
380	func findRemoteInfoForHost(repo *git.Repository, host string) (*Info, bool) {
381		cfg, err := repo.Config()
382		if err != nil {
383			return nil, false
384		}
385		names := make([]string, 0, len(cfg.Remotes))
386		for name := range cfg.Remotes {
387			names = append(names, name)
388		}
389		sort.Strings(names)
390		for _, name := range names {
391			for _, rawURL := range cfg.Remotes[name].URLs {
392				info, err := gitremote.ParseURL(rawURL)
393				if err != nil {
394					continue
395				}
396				if strings.EqualFold(info.Host, host) && isDerivableProtocol(info.Protocol) {
397					return info, true
398				}
399			}
400		}
401		return nil, false
402	}
403	
404	func deriveTokenOriginURL(originURL string) (string, bool) {
405		info, err := gitremote.ParseURL(originURL)
406		if err != nil {
407			return "", false
408		}
409		if info.Host == "" || info.Owner == "" || info.Repo == "" {
410			return "", false
411		}
412		// Keep the port only when the source was already HTTPS. SSH ports
413		// (e.g., :2222) don't map to HTTPS ports on the same host.
414		hostPort := info.Host
415		if info.Protocol == ProtocolHTTPS {
416			hostPort = info.HostPort()
417		}
418		return fmt.Sprintf("https://%s/%s/%s.git", hostPort, info.Owner, info.Repo), true
419	}
420	
421	func providerHost(provider string) (string, bool) {
422		switch strings.ToLower(strings.TrimSpace(provider)) {
423		case "github":
424			return "github.com", true
425		case "gitlab":
426			return "gitlab.com", true
427		default:
428			return "", false
429		}
430	}
431	
432	// RedactURL removes credentials and query parameters from a URL for safe logging.
433	func RedactURL(rawURL string) string {
434		return gitremote.RedactURL(rawURL)
435	}
436	
437	func logFallback(ctx context.Context, operation, fallbackURL, reason string, err error, attrs ...any) {
438		logAttrs := []any{
439			slog.String("operation", operation),
440			slog.String("fallback_url", RedactURL(fallbackURL)),
441			slog.String("reason", reason),
442			slog.String("error", err.Error()),
443		}
444		logAttrs = append(logAttrs, attrs...)
445		logging.Warn(ctx, "checkpoint remote URL resolution fell back to alternate remote URL", logAttrs...)
446	}
447	
448	func resolvePushFallbackURL(ctx context.Context, pushRemoteName, originURL string) (string, error) {
449		if originURL != "" {
450			if strings.TrimSpace(os.Getenv(CheckpointTokenEnvVar)) != "" {
451				if tokenURL, ok := deriveTokenOriginURL(originURL); ok {
452					return tokenURL, nil
453				}
454			}
455			return originURL, nil
456		}
457		if pushRemoteName == "" {
458			return "", fmt.Errorf("no push remote specified and remote %q not found", originRemote)
459		}
460		if pushRemoteName == originRemote {
461			return "", fmt.Errorf("remote %q not found", originRemote)
462		}
463		pushURL, err := GetRemoteURL(ctx, pushRemoteName)
464		if err != nil {
465			return "", err
466		}
467		if strings.TrimSpace(os.Getenv(CheckpointTokenEnvVar)) != "" {
468			if tokenURL, ok := deriveTokenOriginURL(pushURL); ok {
469				return tokenURL, nil
470			}
471		}
472		return pushURL, nil
473	}
